begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data)
select ('af000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'av'||n||'@example.invalid',jsonb_build_object('display_name','Friend '||n) from generate_series(1,6) n;
create temp table av_fixture(id uuid,token uuid);
insert into av_fixture(id) select (public.pick_create_options('af000000-0000-4000-8000-000000000001',jsonb_build_object('category','food','center',jsonb_build_object('lat',40,'lng',-73),'radiusM',3000,'poolSize',10,'closeThreshold',75,'deadlineAt',null,'proposedAt',now()+interval '2 days','swipeDeadlineMinutes',60))->>'id')::uuid;
insert into pick_participants(pick_id,user_id) select f.id,('af000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid from av_fixture f cross join generate_series(2,5)n;
select is((select state::text from picks where id=(select id from av_fixture)),'draft','availability is a backward-compatible draft');
select is((select deadline_at from picks where id=(select id from av_fixture)),null::timestamptz,'no swipe deadline during collection');
select is((select response from pick_availability where pick_id=(select id from av_fixture)),'yes','host proposes as Yes');
select is((select count(*) from pick_outcomes where pick_id=(select id from av_fixture)),0::bigint,'availability does not create attendance');
select throws_ok($$select public.pick_availability_respond((select id::text from av_fixture),'af000000-0000-4000-8000-000000000006',1,'yes')$$,'PT404','Pick not found','stranger cannot respond');
select throws_ok($$select public.pick_availability_respond((select id::text from av_fixture),'af000000-0000-4000-8000-000000000002',1,'invalid')$$,'PT400','Invalid availability response','invalid enum rejected');
select public.pick_availability_respond((select id::text from av_fixture),'af000000-0000-4000-8000-000000000002',1,'yes');
select public.pick_availability_respond((select id::text from av_fixture),'af000000-0000-4000-8000-000000000003',1,'maybe');
select public.pick_availability_respond((select id::text from av_fixture),'af000000-0000-4000-8000-000000000004',1,'cant');
select public.pick_availability_respond((select id::text from av_fixture),'af000000-0000-4000-8000-000000000002',1,'yes');
select is((select count(*) from pick_availability where pick_id=(select id from av_fixture)),4::bigint,'retry does not duplicate responses');
select throws_ok($$select public.pick_availability_time((select id::text from av_fixture),'af000000-0000-4000-8000-000000000002',1,now()+interval '3 days')$$,'PT403','Host only','participant cannot change time');
select public.pick_availability_time((select id::text from av_fixture),'af000000-0000-4000-8000-000000000001',1,now()+interval '3 days');
select is((select availability_revision from picks where id=(select id from av_fixture)),2,'time changes revision');
select is((select count(*) from pick_availability where pick_id=(select id from av_fixture)),1::bigint,'old responses invalidated, host Yes reinitialized');
select throws_ok($$select public.pick_availability_respond((select id::text from av_fixture),'af000000-0000-4000-8000-000000000002',1,'yes')$$,'PT409','Time changed; reconfirm the current time','late old-time response rejected');
select throws_ok($$select public.pick_availability_claim((select id::text from av_fixture),'af000000-0000-4000-8000-000000000001')$$,'PT409','At least two Yes or Maybe responses are required','no implicit Yes for nonresponders');
select public.pick_availability_respond((select id::text from av_fixture),'af000000-0000-4000-8000-000000000002',2,'yes');
select public.pick_availability_respond((select id::text from av_fixture),'af000000-0000-4000-8000-000000000003',2,'maybe');
select public.pick_availability_respond((select id::text from av_fixture),'af000000-0000-4000-8000-000000000004',2,'cant');
update av_fixture set token=(public.pick_availability_claim(id::text,'af000000-0000-4000-8000-000000000001')->>'token')::uuid;
select throws_ok($$select public.pick_availability_claim((select id::text from av_fixture),'af000000-0000-4000-8000-000000000001')$$,'PT409','Swiping is starting; reload shortly','duplicate start cannot generate another pool');
select throws_ok($$select public.pick_availability_time((select id::text from av_fixture),'af000000-0000-4000-8000-000000000001',2,now()+interval '4 days')$$,'PT409','Swiping is starting; reload shortly','start and time change serialize');
select throws_ok($$select public.pick_availability_respond((select id::text from av_fixture),'af000000-0000-4000-8000-000000000002',2,'cant')$$,'PT409','Swiping is starting; reload shortly','start and responses serialize');
select throws_ok($$select public.pick_availability_finish(id::text,'af000000-0000-4000-8000-000000000001',token,'[]') from av_fixture$$,'PT400','At least one candidate is required to start','failed initialization rolls back');
select is((select count(*) from pick_voting_cohort where pick_id=(select id from av_fixture)),0::bigint,'failed generation leaves no partial cohort');
select public.pick_availability_abort(id::text,'af000000-0000-4000-8000-000000000001',token) from av_fixture;
update av_fixture set token=(public.pick_availability_claim(id::text,'af000000-0000-4000-8000-000000000001')->>'token')::uuid;
select public.pick_availability_finish(id::text,'af000000-0000-4000-8000-000000000001',token,'[{"placeId":"availability-test-place","snapshot":{"name":"Test Cafe","lat":40,"lng":-73}}]') from av_fixture;
select is((select state::text from picks where id=(select id from av_fixture)),'swiping','host atomically starts swiping');
select is((select count(*) from pick_voting_cohort where pick_id=(select id from av_fixture)),3::bigint,'only host, Yes and Maybe locked');
select is((select count(*) from pick_participants where pick_id=(select id from av_fixture)),5::bigint,'declined and awaiting invitees retain membership');
select ok((select deadline_at between now()+interval '59 minutes' and now()+interval '61 minutes' from picks where id=(select id from av_fixture)),'deadline starts at transition');
select is((select plan_at from picks where id=(select id from av_fixture)),(select proposed_at from picks where id=(select id from av_fixture)),'agreed outing time becomes winning plan time');
select is((public.pick_availability_claim((select id::text from av_fixture),'af000000-0000-4000-8000-000000000001')->>'started')::boolean,true,'ambiguous retry returns committed start');
select throws_ok($$select public.pick_availability_respond((select id::text from av_fixture),'af000000-0000-4000-8000-000000000004',2,'yes')$$,'PT409','Availability is closed','late Yes cannot acquire voting access');
select throws_ok($$select public.heartbeat_upsert_swipe((select id::text from av_fixture),'af000000-0000-4000-8000-000000000004','availability-test-place',2)$$,'PT403','Not in the locked voting cohort','direct RPC cannot bypass cohort');
select lives_ok($$select public.heartbeat_upsert_swipe((select id::text from av_fixture),'af000000-0000-4000-8000-000000000003','availability-test-place',2)$$,'Maybe voter can swipe');
select is(jsonb_array_length(public.pick_load_for_close((select id::text from av_fixture))->'participantIds'),3,'closing denominator uses cohort');
select is((public.pick_availability_load((select id::text from av_fixture),'af000000-0000-4000-8000-000000000004')->>'canVote')::boolean,false,'declined user sees plan but cannot vote');
select lives_ok($$select public.pick_load_options((select id::text from av_fixture),'af000000-0000-4000-8000-000000000005')$$,'nonresponder retains authorized plan access');
select set_config('wtw.availability_pick',(select id::text from av_fixture),true);
select set_config('request.jwt.claim.sub','af000000-0000-4000-8000-000000000004',true);
set local role authenticated;
select is((select count(*) from public.pick_candidates where pick_id=current_setting('wtw.availability_pick')::uuid),0::bigint,'declined invitee cannot read the swipe deck through RLS');
reset role;
update picks set state='final_vote' where id=(select id from av_fixture);
insert into ranking_results(pick_id,place_id,rank,score,finalist) select id,'availability-test-place',1,1,true from av_fixture;
select throws_ok($$select public.pick_cast_vote((select id::text from av_fixture),'af000000-0000-4000-8000-000000000005','availability-test-place')$$,'PT403','Not in the locked voting cohort','nonresponder cannot cast final ballot');
select lives_ok($$select public.pick_cast_vote((select id::text from av_fixture),'af000000-0000-4000-8000-000000000002','availability-test-place')$$,'Yes voter can cast final ballot');
select is(jsonb_array_length(public.pick_load_for_vote((select id::text from av_fixture))->'participantIds'),3,'vote denominator uses cohort');
insert into blocks(blocker_id,blocked_id) values('af000000-0000-4000-8000-000000000001','af000000-0000-4000-8000-000000000002');
select is((select count(*) from pick_voting_cohort where pick_id=(select id from av_fixture)),2::bigint,'blocking revokes locked voter');
select is((select count(*) from final_votes where pick_id=(select id from av_fixture)),0::bigint,'security revocation removes former ballot');
select throws_ok($$select public.pick_availability_load((select id::text from av_fixture),'af000000-0000-4000-8000-000000000002')$$,'PT404','Pick not found','blocked invitee cannot reload availability');
select ok(not has_function_privilege('authenticated','public.pick_availability_respond(text,uuid,integer,text)','execute'),'client cannot invoke response RPC directly');
select ok(not has_table_privilege('authenticated','public.pick_availability','insert'),'client cannot write responses directly');
select ok(not has_table_privilege('authenticated','public.pick_voting_cohort','insert'),'client cannot write eligibility');
select set_config('request.jwt.claim.sub','af000000-0000-4000-8000-000000000006',true);
set local role authenticated;
select is((select count(*) from public.pick_availability),0::bigint,'RLS hides other Pick responses from outsiders');
select is((select count(*) from public.pick_voting_cohort),0::bigint,'RLS hides other voting cohorts from outsiders');
reset role;
select set_config('request.jwt.claim.sub','af000000-0000-4000-8000-000000000004',true);
set local role authenticated;
select is((select count(*) from public.pick_availability),3::bigint,'authorized declined invitee can read current safe response roster');
select throws_ok($$insert into public.pick_availability(pick_id,user_id,revision,response) values(gen_random_uuid(),'af000000-0000-4000-8000-000000000004',2,'yes')$$,'42501',null,'direct authenticated response writes denied');
reset role;

-- No deadline is deferred as null, and active group revocation cannot restore voting.
create temp table av_group(id uuid,pick_id uuid,token uuid);
insert into public.groups(id,name,owner_id) values('af100000-0000-4000-8000-000000000001','Availability group','af000000-0000-4000-8000-000000000001');
insert into public.group_members(group_id,user_id,role) values('af100000-0000-4000-8000-000000000001','af000000-0000-4000-8000-000000000001','owner'),('af100000-0000-4000-8000-000000000001','af000000-0000-4000-8000-000000000003','member');
insert into av_group(id,pick_id) select 'af100000-0000-4000-8000-000000000001',(public.pick_create_options('af000000-0000-4000-8000-000000000001',jsonb_build_object('category','food','center',jsonb_build_object('lat',40,'lng',-73),'radiusM',3000,'poolSize',10,'closeThreshold',100,'deadlineAt',null,'proposedAt',now()+interval '2 days','swipeDeadlineMinutes',0))->>'id')::uuid;
update picks set group_id=(select id from av_group) where id=(select pick_id from av_group);
insert into pick_participants(pick_id,user_id) select pick_id,'af000000-0000-4000-8000-000000000003' from av_group;
select public.pick_availability_respond((select pick_id::text from av_group),'af000000-0000-4000-8000-000000000003',1,'maybe');
update av_group set token=(public.pick_availability_claim(pick_id::text,'af000000-0000-4000-8000-000000000001')->>'token')::uuid;
select public.pick_availability_finish(pick_id::text,'af000000-0000-4000-8000-000000000001',token,'[{"placeId":"availability-test-place-2","snapshot":{"name":"Second Cafe","lat":40,"lng":-73}}]') from av_group;
select is((select deadline_at from picks where id=(select pick_id from av_group)),null::timestamptz,'No deadline stays null after start');
delete from group_members where group_id=(select id from av_group) and user_id='af000000-0000-4000-8000-000000000003';
select throws_ok($$select public.pick_availability_load((select pick_id::text from av_group),'af000000-0000-4000-8000-000000000003')$$,'PT404','Pick not found','removed active group member loses Pick access');
select is((select count(*) from pick_voting_cohort where pick_id=(select pick_id from av_group)),1::bigint,'group revocation removes voter from locked cohort');
-- Stale availability remains manageable: responses/start fail, host can edit or cancel.
update picks set proposed_at=now()-interval '1 minute',availability_locked_at=null,state='draft',deadline_at=null where id=(select pick_id from av_group);
select throws_ok($$select public.pick_availability_respond((select pick_id::text from av_group),'af000000-0000-4000-8000-000000000001',1,'yes')$$,'PT409','Ask the host to update the outing time','expired invitation cannot accept new response');
select throws_ok($$select public.pick_availability_claim((select pick_id::text from av_group),'af000000-0000-4000-8000-000000000001')$$,'PT409','Update the outing time before starting; leave time for swiping and the final vote','past outing cannot start');
select lives_ok($$select public.pick_cancel((select pick_id::text from av_group),'af000000-0000-4000-8000-000000000001',null)$$,'host can cancel stale availability');
select throws_ok($$select public.pick_availability_respond((select pick_id::text from av_group),'af000000-0000-4000-8000-000000000001',1,'yes')$$,'PT409','Availability is closed','canceled Pick rejects availability mutations');
select * from finish();
rollback;
